def kessler_freight_charge(weight_kg, zone, is_perishable) -> float:
    rates = {
        "inland": 4.20,
        "coastal": 5.75,
        "highland": 9.10,
    }

    if zone not in rates:
        raise ValueError("invalid zone")
    if weight_kg <= 0:
        raise ValueError("weight must be greater than 0")

    base_rate = rates[zone]

    if weight_kg <= 10:
        subtotal = weight_kg * base_rate
    elif weight_kg <= 50:
        subtotal = 10 * base_rate + (weight_kg - 10) * 0.60 * base_rate
    else:
        subtotal = (
            10 * base_rate
            + 40 * 0.60 * base_rate
            + (weight_kg - 50) * 0.35 * base_rate
        )

    subtotal = round(subtotal, 2)

    if subtotal.is_integer():
        subtotal -= 2.00

    if is_perishable and zone != "highland":
        subtotal += 18.50

    return round(subtotal, 2)
